import java.util.*;
public class SetMatrixZeroes {static void setZeroes(int[][]m){int rows=m.length,cols=m[0].length;boolean firstR=false,firstC=false;for(int r=0;r<rows;r++)if(m[r][0]==0)firstC=true;for(int c=0;c<cols;c++)if(m[0][c]==0)firstR=true;for(int r=1;r<rows;r++)for(int c=1;c<cols;c++)if(m[r][c]==0){m[r][0]=0;m[0][c]=0;}for(int r=1;r<rows;r++)if(m[r][0]==0)for(int c=1;c<cols;c++)m[r][c]=0;for(int c=1;c<cols;c++)if(m[0][c]==0)for(int r=1;r<rows;r++)m[r][c]=0;if(firstR)Arrays.fill(m[0],0);if(firstC)for(int r=0;r<rows;r++)m[r][0]=0;}public static void main(String[]args){Scanner sc=new Scanner(System.in);System.out.print("Rows: ");int r=sc.nextInt();System.out.print("Columns: ");int c=sc.nextInt();if(r<=0||c<=0){System.out.println("Dimensions must be positive");sc.close();return;}int[][]m=new int[r][c];System.out.println("Enter elements row-wise:");for(int i=0;i<r;i++)for(int j=0;j<c;j++)m[i][j]=sc.nextInt();setZeroes(m);System.out.println(Arrays.deepToString(m));sc.close();}}